/**
 *
 * SelectPopup is the popup container that wraps the dropdown content inside the positioner.
 *
 * [Live Demo](https://www.primereact.org/select/)
 *
 * @module SelectPopup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseMotionProps } from '@primereact/types/headless/motion';
import type { SelectRootInstance } from './SelectRoot.types';
/**
 * Defines passthrough(pt) options type in SelectPopup component.
 */
export type SelectPopupPassThroughType<E> = PassThroughType<SelectPopupInstance, E>;
/**
 * Defines passthrough(pt) options of SelectPopup component.
 */
export interface SelectPopupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SelectPopupPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SelectPopup component.
 */
export interface SelectPopupProps extends BaseComponentProps<SelectPopupInstance, unknown, SelectPopupPassThrough> {
    /**
     * Used to apply motion to the popup element. It accepts the same properties as useMotion hook.
     */
    motionProps?: UseMotionProps | undefined;
}
/**
 * Defines valid state in SelectPopup component.
 */
export interface SelectPopupState {
}
/**
 * Defines the methods and properties exposed by SelectPopup component.
 */
export interface SelectPopupExposes {
    /**
     * The Select component instance.
     */
    select: SelectRootInstance | undefined | null;
}
/**
 * Instance of SelectPopup component.
 */
export type SelectPopupInstance = ComponentInstance<SelectPopupProps, SelectPopupState, SelectPopupExposes>;
